//! The cross-binding suite's reference renderer: reads the case list
//! (`tests/bindings/cases.jsonl`, generated by `tools/gen_cross_cases.py`)
//! and renders every case through the same safe surface every binding
//! calls — `Options::enable_builtin` and the one-shot `render_html` —
//! writing one JSON line per case:
//!
//! ```json
//! {"name":"spec 1","html":"<p>foo\tbaz\t\tbim</p>\n"}
//! ```
//!
//! The bindings' runners write the same shape for the same cases; the
//! driver (`tools/cross_binding.py`) requires the files to match byte
//! for byte. Run with:
//!
//! ```sh
//! cargo run -p geist4-ffi --bin cross_reference -- cases.jsonl results.jsonl
//! ```

use std::io::Write as _;
use std::path::PathBuf;
use std::process::ExitCode;

use geist4_ffi::safe::{Options, render_html};

fn main() -> ExitCode {
    let mut args = std::env::args().skip(1);
    let cases_path = PathBuf::from(
        args.next()
            .unwrap_or_else(|| usage("missing the cases path")),
    );
    let results_path = PathBuf::from(
        args.next()
            .unwrap_or_else(|| usage("missing the results path")),
    );

    let cases = match std::fs::read_to_string(&cases_path) {
        Ok(cases) => cases,
        Err(error) => {
            eprintln!(
                "cross_reference: cannot read {}: {error}",
                cases_path.display()
            );
            return ExitCode::from(2);
        }
    };

    let results = match std::fs::File::create(&results_path) {
        Ok(results) => results,
        Err(error) => {
            eprintln!(
                "cross_reference: cannot create {}: {error}",
                results_path.display()
            );
            return ExitCode::from(2);
        }
    };
    let mut out = std::io::BufWriter::new(results);

    for (number, line) in cases.lines().enumerate() {
        if line.is_empty() {
            continue;
        }
        let case: serde_json::Value = match serde_json::from_str(line) {
            Ok(case) => case,
            Err(error) => {
                eprintln!("cross_reference: case {} is not JSON: {error}", number + 1);
                return ExitCode::from(2);
            }
        };
        let name = case
            .get("name")
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default();
        let source = case
            .get("source")
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default();
        let mut options = Options::new();
        if let Some(names) = case.get("options").and_then(serde_json::Value::as_array) {
            for value in names {
                let Some(builtin) = value.as_str() else {
                    eprintln!("cross_reference: case {name} has a non-string option");
                    return ExitCode::from(2);
                };
                if let Err(error) = options.enable_builtin(builtin) {
                    eprintln!("cross_reference: case {name}: {error}");
                    return ExitCode::from(2);
                }
            }
        }
        let html = match render_html(source, Some(&options)) {
            Ok(html) => html,
            Err(error) => {
                eprintln!("cross_reference: case {name}: the engine panicked: {error}");
                return ExitCode::from(3);
            }
        };
        let record = serde_json::json!({ "name": name, "html": html });
        if writeln!(out, "{record}").is_err() {
            eprintln!("cross_reference: cannot write {}", results_path.display());
            return ExitCode::from(2);
        }
    }
    match out.flush() {
        Ok(()) => ExitCode::SUCCESS,
        Err(error) => {
            eprintln!("cross_reference: cannot flush: {error}");
            ExitCode::from(2)
        }
    }
}

fn usage(message: &str) -> ! {
    eprintln!("cross_reference: {message}");
    eprintln!("usage: cross_reference <cases.jsonl> <results.jsonl>");
    std::process::exit(2);
}
